{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C65"],
      "claim": "Absolute oral bioavailability of the tricyclic antipsychotic flupentixol was 40.4% (mean; range 24–71%) in patients, supporting high F for a related tricyclic psychotropic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Absolute oral bioavailability of trazodone was 82% in fasted young men, showing high oral availability for a heteroaryl-piperazine psychotropic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Absolute oral bioavailability of imidafenacin was 57.8% (95% CI 54.1–61.4) in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Absolute oral bioavailability of vilazodone was 72% with food.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Oral bioavailability of phenylethylmalonamide was at least 80% in normal subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Absolute oral bioavailability of odanacatib was 30% at 50 mg fasted, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Oral bioavailability of pentopril was 50–70% in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Oral bioavailability of carbamazepine epoxide was at least 78%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Absolute oral bioavailability of benazeprilat from oral benazepril was 27.1–28.5%, above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Oral bioavailability of encainide was 30 ± 7% in normal subjects, above the threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence points to absolute oral bioavailability above 20%: direct human F values for close tricyclic/piperazine psychotropics and other drug-like analogues range from ~27% to >80%, with no affirmative evidence of F < 20%. The query's phenothiazine-like scaffold and polar amide/sulfone groups are consistent with adequate oral absorption, so high bioavailability is predicted.",
  "evidence_gaps": [
    "No direct absolute bioavailability study of the exact query molecule.",
    "The query's specific combination of methylsulfonyl phenothiazine and carbamoylpiperidine is not identical to any evidence molecule; extrapolation relies on related structures.",
    "First-pass metabolism and transporter effects for the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

